const dialog=document.createElement('dialog');dialog.id='aks-dialog';document.body.appendChild(dialog);
const btn=(act,label,cls='',attrs='')=>`<button type="button" data-act="${act}" class="${cls}" ${attrs}>${label}</button>`;
const field=(n,label,value='',type='text',attrs='')=>`<div class="field"><label for="f-${n}">${label}</label><input id="f-${n}" name="${n}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const area=(n,label,value='',attrs='')=>`<div class="field"><label for="f-${n}">${label}</label><textarea id="f-${n}" name="${n}" ${attrs}>${esc(value)}</textarea></div>`;
const options=(opts,val)=>opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(l)}</option>`;}).join('');
const select=(n,label,opts,val='',attrs='')=>`<div class="field"><label for="f-${n}">${label}</label><select id="f-${n}" name="${n}" ${attrs}>${options(opts,val)}</select></div>`;
